def _split_escape_string(
    input: Any, keep_escape: Any = True, splitchar: Any = ',', escapechar: Any = '\\'
) -> object {
    results = [];
    string = "";
    escaped = False;
    for c in input {
        if (not escaped and (c == escapechar)) {
            escaped = True;
            if keep_escape {
                string += c;
            }
        } elif (not escaped and (c == splitchar)) {
            results.append(string);
            string = "";
        } else {
            string += c;
            escaped = False;
        }
    }
    results.append(string);
    return results;
}

